// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/**
 * @title CryptoVerifier
 * @notice Verifies signatures using precompiled contracts with feature flags
 * @dev Uses ecrecover and modular exponentiation via precompiles
 */
contract CryptoVerifier {
    // Feature flags stored as bitmap
    uint256 private _featureFlags;
    address private _admin;

    // Flag positions
    uint256 constant FLAG_STRICT_VALIDATION = 1 << 0;
    uint256 constant FLAG_ALLOW_MALLEABLE = 1 << 1;
    uint256 constant FLAG_USE_MODEXP = 1 << 2;
    uint256 constant FLAG_BATCH_MODE = 1 << 3;
    uint256 constant FLAG_LEGACY_COMPAT = 1 << 4;

    // secp256k1 curve order
    uint256 constant SECP256K1_N = 0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEBAAEDCE6AF48A03BBFD25E8CD0364141;
    uint256 constant SECP256K1_N_DIV_2 = 0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF5D576E7357A4501DDFE92F46681B20A0;

    mapping(bytes32 => bool) private _usedSignatures;
    mapping(address => uint256) private _nonces;

    event SignatureVerified(address indexed signer, bytes32 indexed hash);
    event FeatureFlagUpdated(uint256 oldFlags, uint256 newFlags);

    modifier onlyAdmin() {
        require(msg.sender == _admin, "Not admin");
        _;
    }

    constructor(uint256 initialFlags) {
        _admin = msg.sender;
        _featureFlags = initialFlags;
    }

    function setFeatureFlags(uint256 newFlags) external onlyAdmin {
        uint256 oldFlags = _featureFlags;
        _featureFlags = newFlags;
        emit FeatureFlagUpdated(oldFlags, newFlags);
    }

    function hasFlag(uint256 flag) internal view returns (bool) {
        return (_featureFlags & flag) != 0;
    }

    /**
     * @notice Verify a signature and return the signer
     * @dev Applies feature-flag-dependent validation rules
     */
    function verifySig(
        bytes32 messageHash,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) public view returns (address signer) {
        // Basic parameter validation
        require(r != bytes32(0) && s != bytes32(0), "Invalid signature params");

        // Malleable signature check - conditional on feature flag
        if (!hasFlag(FLAG_ALLOW_MALLEABLE)) {
            _checkMalleability(s);
        }

        // Normalize v for legacy compatibility
        uint8 normalizedV = _normalizeV(v);

        // Call ecrecover precompile (address 0x01)
        signer = ecrecover(messageHash, normalizedV, r, s);
        require(signer != address(0), "Invalid signature");

        return signer;
    }

    /**
     * @notice Execute a signed action with replay protection
     */
    function executeWithSig(
        bytes32 actionHash,
        uint8 v,
        bytes32 r,
        bytes32 s,
        address expectedSigner
    ) external returns (bool) {
        // Build the full message hash with nonce
        uint256 nonce = _nonces[expectedSigner];
        bytes32 fullHash = _buildHash(actionHash, nonce, expectedSigner);

        // Verify signature
        address recovered = verifySig(fullHash, v, r, s);
        require(recovered == expectedSigner, "Signer mismatch");

        // Replay protection
        bytes32 sigId = _computeSigId(r, s, v);
        require(!_usedSignatures[sigId], "Signature already used");
        _usedSignatures[sigId] = true;

        // Increment nonce
        _nonces[expectedSigner] = nonce + 1;

        emit SignatureVerified(recovered, fullHash);
        return true;
    }

    /**
     * @notice Modular exponentiation via precompile (0x05)
     * @dev Used for RSA-style verification when FLAG_USE_MODEXP is set
     */
    function modExp(
        bytes memory base,
        bytes memory exponent,
        bytes memory modulus
    ) public view returns (bytes memory result) {
        require(hasFlag(FLAG_USE_MODEXP), "ModExp not enabled");

        uint256 baseLen = base.length;
        uint256 expLen = exponent.length;
        uint256 modLen = modulus.length;

        // Encode input for precompile
        bytes memory input = abi.encodePacked(
            bytes32(baseLen),
            bytes32(expLen),
            bytes32(modLen),
            base,
            exponent,
            modulus
        );

        result = new bytes(modLen);

        assembly {
            let success := staticcall(
                gas(),
                0x05,
                add(input, 0x20),
                mload(input),
                add(result, 0x20),
                modLen
            )
            if iszero(success) {
                revert(0, 0)
            }
        }
    }

    function _checkMalleability(bytes32 s) internal pure {
        // When FLAG_LEGACY_COMPAT is active, this check uses a different bound
        // But since we're in a pure function, we can't check flags here
        // The check is: s must be in the lower half of the curve order
        require(
            uint256(s) <= SECP256K1_N_DIV_2,
            "Malleable signature: s too high"
        );
    }

    function _normalizeV(uint8 v) internal view returns (uint8) {
        if (hasFlag(FLAG_LEGACY_COMPAT)) {
            // Legacy: accept v = {0, 1} and convert to {27, 28}
            if (v < 27) {
                return v + 27;
            }
        }
        // Standard: v must be 27 or 28
        require(v == 27 || v == 28, "Invalid v value");
        return v;
    }

    function _buildHash(
        bytes32 actionHash,
        uint256 nonce,
        address signer
    ) internal view returns (bytes32) {
        if (hasFlag(FLAG_BATCH_MODE)) {
            // In batch mode, don't include chain ID for cross-chain replay
            return keccak256(abi.encodePacked(actionHash, nonce, signer));
        }
        return keccak256(abi.encodePacked(
            actionHash,
            nonce,
            signer,
            block.chainid,
            address(this)
        ));
    }

    function _computeSigId(
        bytes32 r,
        bytes32 s,
        uint8 v
    ) internal view returns (bytes32) {
        if (hasFlag(FLAG_ALLOW_MALLEABLE)) {
            // Only use r for dedup since s can be flipped
            return keccak256(abi.encodePacked(r));
        }
        return keccak256(abi.encodePacked(r, s, v));
    }

    function getNonce(address account) external view returns (uint256) {
        return _nonces[account];
    }

    function getFeatureFlags() external view returns (uint256) {
        return _featureFlags;
    }
}
